G.midi=(r,lv)=>{if(r()<.35){const names=['C','C♯','D','E♭','E','F','F♯','G','A♭','A','B♭','B'];const m=48+Math.floor(r()*25);const nm=names[m%12]+(Math.floor(m/12)-1);const opts=shuffle(r,[m,m+1,m-1,m+12].map(String));return{prompt:`What MIDI note number is ${nm}?`,meta:'Middle C (C4) is 60',options:opts,answer:String(m),explain:`Count up or down from 60. ${nm} is ${m}.`}}return bankQ(r,lv,QB_MIDI)};

G.harmony=(r,lv)=>{const keys=lv===0?['C','G','F']:['C','G','D','A','F','Bb','Eb','E'];const key=keys[Math.floor(r()*keys.length)];const kind=['dia','dia','cad','sec','bor'][Math.floor(r()*(lv===0?3:5))];
 if(kind==='dia'){const d=1+Math.floor(r()*7);const c=chordAt(key,'major',d,DIA.major.sev[d-1]);const others=[1,2,3,4,5,6,7].filter(x=>x!==d).map(x=>chordAt(key,'major',x,DIA.major.sev[x-1]).sym);return{prompt:`In ${pr(key)} major, which chord is ${c.roman}?`,meta:'Seventh chords in a key',options:mkOpts(r,c.sym,shuffle(r,others)),answer:c.sym,explain:`Count up the ${pr(key)} major scale to degree ${d}: ${c.sym}.`,reveal:()=>play(voice(c.root,c.t))}}
 if(kind==='cad'){const C=[['V–I','Perfect (authentic)'],['IV–I','Plagal'],['I–V (ending on V)','Imperfect (half)'],['V–vi','Interrupted (deceptive)']];const[q,a]=C[Math.floor(r()*4)];return{prompt:`A phrase ends ${q}. What kind of cadence is it?`,options:shuffle(r,C.map(x=>x[1])),answer:a,explain:`${q} is ${a.toLowerCase()}.`}}
 if(kind==='sec'){const tg=[2,4,5,6][Math.floor(r()*4)];const t=chordAt(key,'major',tg);const root=spellUp(t.root,7,5);const ans=chordSym(root,'7');const dis=[chordSym(t.root,'7'),chordAt(key,'major',5,'7').sym,chordSym(spellUp(t.root,5,4),'7'),chordAt(key,'major',((tg+3)%7)+1,'m7').sym];return{prompt:`In ${pr(key)} major, what is V7 of ${t.roman} (V7/${t.roman})?`,meta:'Secondary dominants',options:mkOpts(r,ans,dis),answer:ans,explain:`${t.roman} is ${t.sym}. A 5th above ${pr(t.root)} is ${pr(root)}, so V7/${t.roman} is ${ans}.`}}
 const B=[[7,'♭VII','maj'],[6,'♭VI','maj'],[3,'♭III','maj'],[4,'iv','min']][Math.floor(r()*4)];const c=chordAt(key,'minor',B[0],B[2]);const dis=[chordAt(key,'major',B[0]).sym,chordAt(key,'major',B[0],'7').sym,chordAt(key,'minor',((B[0]+1)%7)+1,B[2]).sym,chordAt(key,'major',((B[0]+2)%7)+1).sym];
 return{prompt:`Which chord is ${B[1]}, borrowed from the minor, in ${pr(key)} major?`,meta:'Borrowed chords',options:mkOpts(r,c.sym,dis),answer:c.sym,explain:`${B[1]} comes from ${pr(key)} minor: ${c.sym}.`,reveal:()=>play(voice(c.root,c.t))}};

